271	pub(crate) fn calc_requirements<
272	    T: Borrow<Arc<dyn PhysicalExpr>>,
273	    S: Borrow<PhysicalSortExpr>,
274	>(
275	    partition_by_exprs: impl IntoIterator<Item = T>,
276	    orderby_sort_exprs: impl IntoIterator<Item = S>,
277	) -> Option<LexRequirement> {
278	    let mut sort_reqs = LexRequirement::new(
279	        partition_by_exprs
280	            .into_iter()
281	            .map(|partition_by| {
282	                PhysicalSortRequirement::new(Arc::clone(partition_by.borrow()), None)
283	            })
284	            .collect::<Vec<_>>(),
285	    );
286	    for element in orderby_sort_exprs.into_iter() {
287	        let PhysicalSortExpr { expr, options } = element.borrow();
288	        if !sort_reqs.iter().any(|e| e.expr.eq(expr)) {
289	            sort_reqs.push(PhysicalSortRequirement::new(
290	                Arc::clone(expr),
291	                Some(*options),
292	            ));
293	        }
294	    }
295	    // Convert empty result to None. Otherwise wrap result inside Some()
296	    (!sort_reqs.is_empty()).then_some(sort_reqs)
297	}
