299	/// This function calculates the indices such that when partition by expressions reordered with the indices
300	/// resulting expressions define a preset for existing ordering.
301	/// For instance, if input is ordered by a, b, c and PARTITION BY b, a is used,
302	/// this vector will be [1, 0]. It means that when we iterate b, a columns with the order [1, 0]
303	/// resulting vector (a, b) is a preset of the existing ordering (a, b, c).
304	pub fn get_ordered_partition_by_indices(
305	    partition_by_exprs: &[Arc<dyn PhysicalExpr>],
306	    input: &Arc<dyn ExecutionPlan>,
307	) -> Vec<usize> {
308	    let (_, indices) = input
309	        .equivalence_properties()
310	        .find_longest_permutation(partition_by_exprs);
311	    indices
312	}
