335	pub(crate) fn window_equivalence_properties(
336	    schema: &SchemaRef,
337	    input: &Arc<dyn ExecutionPlan>,
338	    window_exprs: &[Arc<dyn WindowExpr>],
339	) -> EquivalenceProperties {
340	    // We need to update the schema, so we can not directly use
341	    // `input.equivalence_properties()`.
342	    let mut window_eq_properties = EquivalenceProperties::new(Arc::clone(schema))
343	        .extend(input.equivalence_properties().clone());
344	
345	    let schema_len = schema.fields.len();
346	    let window_expr_indices =
347	        ((schema_len - window_exprs.len())..schema_len).collect::<Vec<_>>();
348	    for (i, expr) in window_exprs.iter().enumerate() {
349	        if let Some(udf_window_expr) = expr.as_any().downcast_ref::<StandardWindowExpr>()
350	        {
351	            udf_window_expr.add_equal_orderings(&mut window_eq_properties);
352	        } else if let Some(aggregate_udf_window_expr) =
353	            expr.as_any().downcast_ref::<PlainAggregateWindowExpr>()
354	        {
355	            let window_expr_index = window_expr_indices[i];
356	            aggregate_udf_window_expr
357	                .add_equal_orderings(&mut window_eq_properties, window_expr_index);
358	        }
359	        // TODO: SlidingAggregateWindowExpr cannot introduce a new ordering yet
360	        //       because we cannot determine whether the window's incoming elements
361	        //       are greater than its outgoing elements. However, we do have
362	        //       the necessary tools to support this, and we can extend support
363	        //       for these cases in the future.
364	    }
365	    window_eq_properties
366	}
